-- 384: Original BrillaPrep flashcards, batch flashcards-beta-001, part 4 of 5.
-- Curriculum-aligned revision content; not official WAEC or NaCCA examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_genetics_03', 'deck_sys_topic_genetics', 'Distinguish between genotype and phenotype.', 'Genotype is the genetic makeup of an organism (the alleles it carries); phenotype is the observable characteristic produced by the genotype interacting with the environment.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_genetics_04', 'deck_sys_topic_genetics', 'Distinguish between homozygous and heterozygous.', 'Homozygous means both alleles of a gene are identical (e.g. TT or tt); heterozygous means the two alleles are different (e.g. Tt).', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_genetics_05', 'deck_sys_topic_genetics', 'State Mendel’s law of segregation.', 'The two alleles of a gene separate (segregate) during gamete formation, so that each gamete carries only one allele of each gene.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_genetics_06', 'deck_sys_topic_genetics', 'State Mendel’s law of independent assortment.', 'Alleles of different genes are distributed to gametes independently of one another, provided the genes are located on different (non-homologous) chromosomes.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_genetics_07', 'deck_sys_topic_genetics', 'In DNA, which bases pair together, and how are they held?', 'Adenine pairs with thymine (two hydrogen bonds) and guanine pairs with cytosine (three hydrogen bonds) — complementary base pairing.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_genetics_08', 'deck_sys_topic_genetics', 'A heterozygous tall pea plant (Tt) is crossed with a dwarf plant (tt). What offspring ratio is expected?', '1 tall : 1 dwarf — half the offspring are Tt (tall) and half are tt (dwarf), as shown by a Punnett square for this test cross.', NULL, 'Draw the Punnett square.', 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_genetics_09', 'deck_sys_topic_genetics', 'What is a mutation?', 'A sudden, heritable change in the structure or amount of DNA; gene mutations alter the base sequence, while chromosome mutations change chromosome structure or number.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_genetics_10', 'deck_sys_topic_genetics', 'What determines the sex of a child in humans?', 'The sex chromosomes: females are XX and males are XY. Eggs always carry X, so the sperm (carrying X or Y) determines whether the zygote is female or male.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_literature_01', 'deck_literature_devices', 'What is a metaphor?', 'A direct comparison that states one thing IS another, without using “like” or “as”: “He is a lion in battle.”', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_literature_02', 'deck_literature_devices', 'What is a simile?', 'A comparison between two unlike things using “like” or “as”: “Her voice is as sweet as honey.”', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_literature_03', 'deck_literature_devices', 'What is personification?', 'Giving human qualities, feelings or actions to non-human things or abstract ideas: “The wind whispered through the trees.”', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_literature_04', 'deck_literature_devices', 'What is alliteration?', 'The repetition of the same initial consonant sound in closely placed words: “Peter Piper picked a peck of pickled peppers.”', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_literature_05', 'deck_literature_devices', 'What is onomatopoeia?', 'A word whose sound imitates the thing it names, such as “buzz”, “hiss” or “bang”.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_literature_06', 'deck_literature_devices', 'What is hyperbole?', 'Deliberate exaggeration used for emphasis or effect and not meant literally: “I have told you a million times.”', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_literature_07', 'deck_literature_devices', 'What is symbolism?', 'Using an object, person, place or action to represent a deeper abstract idea beyond its literal meaning — for example, a dove symbolising peace.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_literature_08', 'deck_literature_devices', 'What is an oxymoron?', 'A figure of speech that joins two contradictory terms in one expression, such as “bittersweet” or “deafening silence”.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_literature_09', 'deck_literature_devices', 'What is a soliloquy?', 'A speech in drama in which a character, alone on stage, speaks their inner thoughts aloud, revealing feelings and motives directly to the audience.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_literature_10', 'deck_literature_devices', 'What are the three types of irony?', 'Verbal irony — saying the opposite of what is meant; situational irony — events turning out contrary to expectation; dramatic irony — the audience knowing more than the characters.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_human_biology_01', 'deck_int_science_human_biology', 'What are the main functions of the human skeleton?', 'Support of the body, protection of delicate organs (the skull protects the brain), movement together with muscles, production of blood cells in the bone marrow, and storage of minerals such as calcium.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_human_biology_02', 'deck_int_science_human_biology', 'Name the four main components of blood and one function of each.', 'Red blood cells transport oxygen; white blood cells defend the body against infection; platelets are responsible for blood clotting; plasma carries nutrients, hormones and waste products.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_human_biology_03', 'deck_int_science_human_biology', 'Describe the double circulation of blood in humans.', 'The right side of the heart pumps deoxygenated blood to the lungs (pulmonary circulation); oxygenated blood returns to the left side, which pumps it around the body (systemic circulation) before it returns to the right side.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_human_biology_04', 'deck_int_science_human_biology', 'What is the function of the alveoli in the lungs?', 'They are the site of gas exchange: oxygen diffuses into the blood and carbon dioxide diffuses out. Their large surface area, thin walls and rich capillary network make diffusion fast.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_human_biology_05', 'deck_int_science_human_biology', 'Where does the digestion of carbohydrates, proteins and fats each begin?', 'Carbohydrates in the mouth (salivary amylase); proteins in the stomach (pepsin, in acid conditions); fats in the small intestine (bile emulsifies them, then pancreatic lipase digests them).', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b001_human_biology_06', 'deck_int_science_human_biology', 'What is the role of the kidneys?', 'They filter the blood to remove urea, excess salts and excess water (excretion) and they regulate the body’s water and salt balance (osmoregulation).', NULL, NULL, 2);
